<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';import GovernanceDrawer from './GovernanceDrawer.vue';import GovernanceResourcePicker from './GovernanceResourcePicker.vue';import {kindLabels,localTime,percent,stateLabels,type Report,type CandidateDetail} from './workbench-types';
const props=defineProps<{id:string}>(),app=useApplication(),ops=app.operationsCommands,route=useRoute(),router=useRouter(),report=ref<Report|null>(null),comparison=ref<Report|null>(null),candidate=ref<CandidateDetail|null>(null),compareId=ref(''),compareOpen=ref(false),error=ref(''),notice=ref(''),busy=ref(false),loading=ref(false),drawer=ref<'cancel'|'approve'|'rubric'|null>(null),reason=ref(''),rubric=ref({factuality:0,actions:0,evidence:0}),reviewSample=ref(''),expanded=ref('');let epoch=0,timer:ReturnType<typeof setTimeout>|null=null,compareEpoch=0;
const actor=()=>app.session.current.value?.actor.enterpriseId,locked=computed(()=>busy.value||ops.pending.value||!ops.available.value),otherAdmin=computed(()=>!!report.value&&report.value.actorId!==actor()&&candidate.value?.creatorId!==actor());
const canApprove=computed(()=>otherAdmin.value&&candidate.value?.state==='DRAFT'&&candidate.value.revisionToken===report.value?.candidateRevision&&report.value?.state==='COMPLETED'&&report.value.qualification.eligible);
async function load(silent=false){const turn=++epoch;error.value='';if(!silent)loading.value=true;if(timer)clearTimeout(timer);try{const r=await ops.read<Report>('/api/v1/operations/reports/'+props.id);if(turn!==epoch)return;report.value=r;candidate.value=null;if(r.candidateId){const c=await ops.read<CandidateDetail>('/api/v1/operations/candidates/'+r.candidateId);if(turn!==epoch)return;candidate.value=c;}if(['PENDING','RUNNING'].includes(r.state))timer=setTimeout(()=>void load(true),2500);}catch(cause){if(turn===epoch)error.value=cause instanceof Error?cause.message:'评测报告暂不可用。';}finally{if(turn===epoch)loading.value=false;}}
watch(()=>props.id,()=>{report.value=null;comparison.value=null;void load();},{immediate:true});
async function compare(){if(!compareId.value||!report.value)return;const turn=++compareEpoch;error.value='';try{const other=await ops.read<Report>('/api/v1/operations/reports/'+compareId.value);if(turn!==compareEpoch)return;if(other.datasetId!==report.value.datasetId)throw Error('请选择同一不可变数据集版本的评测；不同数据集不能直接比较。');if(other.id===report.value.id)throw Error('请选择另一份评测报告。');comparison.value=other;compareOpen.value=false;await router.replace({query:{...route.query,compare:other.id}});}catch(cause){error.value=cause instanceof Error?cause.message:'比较报告暂不可用。';}}
async function action(path:string,body:unknown,message:string,redirect=false){if(locked.value)return;busy.value=true;error.value='';try{const result=await ops.submit(path,body) as {id:string};notice.value=message;drawer.value=null;reason.value='';if(redirect)await router.push('/operations/evaluation/'+result.id);else await load(true);}catch(cause){error.value=cause instanceof Error?cause.message:'操作结果尚未确认，请保留原请求。';}finally{busy.value=false;}}
function cancel(){return action(`/api/v1/operations/evaluations/${props.id}/cancellation`,{reason:reason.value},'评测已取消，已完成样本保留。');}
function retry(){return action(`/api/v1/operations/evaluations/${props.id}/retries`,{},'已创建新的评测，成功样本沿用原结果。',true);}
function approve(){if(!candidate.value||!report.value)return;return action(`/api/v1/operations/candidates/${candidate.value.id}/approval`,{expectedRevisionToken:candidate.value.revisionToken,evaluationId:report.value.id,reason:reason.value},'独立复核已记录，可在系统配置中发布。');}
function saveRubric(){return action(`/api/v1/operations/evaluations/${props.id}/samples/${reviewSample.value}/review`,{rubric:rubric.value,reason:reason.value},'该样本的人工评分已保存。');}
function openRubric(id:string){reviewSample.value=id;rubric.value={factuality:0,actions:0,evidence:0};reason.value='';drawer.value='rubric';}
function result(id:string){return report.value?.results.find(r=>r.id===id);}
const matrix=computed(()=>{const m={tp:0,tn:0,fp:0,fn:0,unknown:0};for(const s of report.value?.samples??[]){if(!s.kind.startsWith('VOICE_'))continue;const r=result(s.id);if(!r?.succeeded||r.measures?.accepted===undefined){m.unknown++;continue;}if(s.kind==='VOICE_SAME')m[r.measures.accepted===1?'tp':'fn']++;else m[r.measures.accepted===0?'tn':'fp']++;}return m;});
const hasVoice=computed(()=>report.value?.samples.some(s=>s.kind.startsWith('VOICE_'))??false);
const sampleLabel=computed(()=>report.value?.samples.find(s=>s.id===reviewSample.value));
watch(()=>report.value?.id,id=>{if(id&&typeof route.query.compare==='string'&&!comparison.value){compareId.value=route.query.compare;void compare();}});
onUnmounted(()=>{epoch++;compareEpoch++;if(timer)clearTimeout(timer);});
</script>
<template><div class="report-heading"><div><RouterLink to="/operations/evaluation" class="gov-muted"><Icon name="arrowL"/> 返回评测记录</RouterLink><h2>质量评测报告</h2><p v-if="report">{{report.datasetVersion}} · {{localTime(report.createdAt)}}</p></div><div class="gov-inline-actions"><button class="btn" :disabled="loading||busy" @click="load()"><Icon name="refresh"/>刷新报告</button><button class="btn" :disabled="!report||busy" @click="compareOpen=true">比较评测</button><button v-if="report&&['PENDING','RUNNING'].includes(report.state)" class="btn" :disabled="locked" @click="drawer='cancel';reason=''">取消评测</button><button v-if="report&&['COMPLETED','CANCELLED'].includes(report.state)&&(report.metrics.failed>0||report.metrics.pending>0)" class="btn" :disabled="locked" @click="retry">重试未成功样本</button><button v-if="canApprove" class="btn primary" :disabled="locked" @click="drawer='approve';reason=''">独立复核通过</button></div></div><p v-if="notice" class="gov-success" role="status">{{notice}}</p><p v-if="error" class="gov-error" role="alert">{{error}}</p><div v-if="loading&&!report" class="gov-loading" role="status">正在读取完整报告…</div><template v-if="report"><div class="report-verdict" :class="{eligible:report.qualification.eligible}"><Icon :name="report.qualification.eligible?'check':'alert'" :size="24"/><div><strong>{{report.qualification.eligible?'各类指标达到冻结规则':report.qualification.mode==='OBSERVATION'?'观察性报告，不具备发布资格':'尚未达到发布条件'}}</strong><p>{{report.state==='PENDING'?'正在等待资源':report.state==='RUNNING'?'评测进行中，结果会自动刷新':stateLabels[report.state]}}<span v-if="report.reviewedBy"> · 已人工复核</span><span v-else-if="report.qualification.eligible"> · 等待另一名管理员复核</span></p><ul v-if="report.qualification.blockers.length"><li v-for="message in report.qualification.blockers" :key="message">{{message}}</li></ul></div></div><div class="gov-summary report-progress"><div><span>总样本</span><strong>{{report.metrics.sampleCount}}</strong></div><div><span>成功执行</span><strong>{{report.metrics.succeeded}}</strong></div><div><span>失败</span><strong>{{report.metrics.failed}}</strong></div><div><span>待处理</span><strong>{{report.metrics.pending}}</strong></div></div><section class="report-card"><header><h3>运行快照</h3><RouterLink v-if="report.candidateId" class="gov-link" :to="{path:'/operations/configuration',query:{selected:report.candidateId}}">查看候选配置 →</RouterLink></header><div class="snapshot-grid"><div><span>数据集版本</span><b>{{report.datasetVersion}}</b></div><div><span>语音模型</span><b>{{report.configuration.modelVersion}}</b></div><div><span>纪要提示词</span><b>{{report.configuration.promptVersion}}</b></div><div><span>声纹阈值</span><b>{{report.configuration.voiceThreshold??'匹配关闭'}}</b></div></div></section><section class="report-card"><header><h3>按任务类型判定</h3><span class="gov-muted">失败与缺失标注会阻止发布</span></header><div class="gov-table-wrap"><table class="gov-table"><thead><tr><th>任务类型</th><th>样本数</th><th>指标</th><th>实际结果</th><th>冻结标准</th><th>判定</th><template v-if="comparison"><th>比较报告结果</th><th>比较报告标准</th></template></tr></thead><tbody><tr v-for="(group,kind) in report.qualification.kinds" :key="kind"><td>{{kindLabels[kind]}}</td><td>{{group.sampleCount}}</td><td>{{group.metric.toUpperCase()}}</td><td>{{group.sufficient?percent(group.value):'待补充依据'}}</td><td>{{['cer','der','far','frr'].includes(group.metric)?'≤':'≥'}} {{percent(group.limit)}}</td><td><span class="gov-tag" :data-state="group.passed?'APPROVED':'PENDING'">{{group.passed?'达标':'未达标'}}</span></td><template v-if="comparison"><td>{{percent(comparison.qualification.kinds[kind]?.value)}}</td><td>{{percent(comparison.qualification.kinds[kind]?.limit)}}</td></template></tr></tbody></table></div><p v-if="comparison" class="comparison-note">对比 {{comparison.id.slice(0,8)}} · 同一数据集 {{comparison.datasetVersion}} · {{comparison.configuration.promptVersion}}<button class="gov-link" @click="comparison=null;router.replace({query:{...route.query,compare:undefined}})">移除比较</button></p><p v-if="hasVoice" class="voice-matrix">声纹判定：正确接受 {{matrix.tp}} · 正确拒绝 {{matrix.tn}} · 错误接受 {{matrix.fp}} · 错误拒绝 {{matrix.fn}} · 未成功判定 {{matrix.unknown}}</p></section><section class="report-card sample-results"><header><h3>逐样本结果与证据</h3><span class="gov-muted">点击样本展开实际输出和参考标注</span></header><article v-for="(sample,index) in report.samples" :key="sample.id"><button class="sample-heading" :aria-expanded="expanded===sample.id" @click="expanded=expanded===sample.id?'':sample.id"><span class="sample-index">{{String(index+1).padStart(2,'0')}}</span><strong>{{kindLabels[sample.kind]}}</strong><span class="gov-muted">{{result(sample.id)?.durationMillis??0}} ms</span><span class="gov-tag" :data-state="!result(sample.id)?'PENDING':result(sample.id)?.succeeded?'COMPLETED':'REJECTED'">{{!result(sample.id)?'待处理':result(sample.id)?.succeeded?'执行成功':'执行失败'}}</span><Icon :name="expanded===sample.id?'arrowL':'arrowR'"/></button><div v-if="expanded===sample.id" class="sample-body"><p v-if="result(sample.id)?.error" class="gov-error">{{result(sample.id)?.error==='INVALID_INPUT_OR_REFERENCE'?'样本或参考标注不符合当前任务要求。':'模型调用未能返回可核实结果。'}} 错误码：{{result(sample.id)?.error}}</p><div class="gov-two"><section><h4>参考标注</h4><pre class="gov-report-pre">{{sample.expected}}</pre></section><section><h4>实际输出</h4><pre class="gov-report-pre">{{result(sample.id)?.actual??'尚无成功输出'}}</pre></section></div><dl class="sample-measures"><template v-for="(value,key) in result(sample.id)?.measures" :key="key"><dt>{{key}}</dt><dd>{{Number(value).toFixed(4)}}</dd></template></dl><template v-if="sample.kind==='MINUTES'"><p class="gov-note">纪要文字相似度只作辅助参考。事实、行动项与证据须由另一名管理员核对。</p><div v-for="review in report.sampleReviews.filter(r=>r.sampleId===sample.id)" :key="review.sampleId"><p>事实 {{percent(review.rubric.factuality)}} · 行动项 {{percent(review.rubric.actions)}} · 证据 {{percent(review.rubric.evidence)}}</p><p class="gov-muted">{{review.reason}}</p></div><button v-if="otherAdmin&&report.state==='COMPLETED'&&result(sample.id)?.succeeded&&!report.reviewedBy&&!report.sampleReviews.some(r=>r.sampleId===sample.id)" class="btn" :disabled="locked" @click="openRubric(sample.id)">填写人工评分</button></template></div></article></section><p v-if="report.reviewReason" class="gov-note">复核意见：{{report.reviewReason}}</p><p class="gov-disclosure">该报告保留受控环境的模型输出与计算结果；通过流程验证不代表真实业务样本已达到相同质量。</p></template>
<GovernanceDrawer v-if="compareOpen" title="比较评测报告" subtitle="只允许比较同一个不可变数据集版本。" :busy="busy" @close="compareOpen=false"><GovernanceResourcePicker module="evaluations" state="COMPLETED" v-model="compareId" label="比较报告"/><p v-if="error" class="gov-error" role="alert">{{error}}</p><template #footer><button class="btn" @click="compareOpen=false">关闭</button><button class="btn primary" :disabled="!compareId" @click="compare">开始比较</button></template></GovernanceDrawer>
<GovernanceDrawer v-if="drawer" :title="drawer==='cancel'?'取消评测':drawer==='approve'?'独立复核':'纪要人工评分'" :wide="drawer==='rubric'" :busy="busy" @close="drawer=null"><p v-if="error" class="gov-error" role="alert">{{error}}</p><div v-if="drawer==='rubric'"><div class="gov-two"><section><h4>参考依据</h4><pre class="gov-report-pre">{{sampleLabel?.expected}}</pre></section><section><h4>实际纪要</h4><pre class="gov-report-pre">{{result(reviewSample)?.actual}}</pre></section></div><div class="gov-fields"><label v-for="[key,label] in [['factuality','事实准确性'],['actions','行动项完整性'],['evidence','证据一致性']] as const" :key="key">{{label}}<select v-model.number="rubric[key]" :disabled="locked"><option :value="0">0 · 不满足 / 缺少证据</option><option :value="0.5">0.5 · 部分满足</option><option :value="1">1 · 完整满足</option></select></label></div></div><p v-else class="gov-note">{{drawer==='cancel'?'取消会停止后续样本处理，已完成的结果和历史记录继续保留。':'请核对各类实际输出、标注依据及冻结规则。复核通过后，该候选才可进入发布步骤。'}}</p><div class="gov-fields"><label>{{drawer==='cancel'?'取消原因':drawer==='approve'?'复核意见':'评分依据'}}<textarea v-model="reason" maxlength="2048" :disabled="locked"/></label></div><template #footer><button class="btn" :disabled="busy" @click="drawer=null">关闭</button><button class="btn primary" :disabled="locked||!reason.trim()" @click="drawer==='cancel'?cancel():drawer==='approve'?approve():saveRubric()">{{drawer==='cancel'?'确认取消':drawer==='approve'?'记录复核结论':'保存评分'}}</button></template></GovernanceDrawer></template>
<style scoped>.report-heading{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:24px}.report-heading h2{font-size:25px;margin:14px 0 6px}.report-heading p{font-size:12px;color:#9195a2}.report-verdict{display:flex;gap:16px;background:#fff6ed;border:1px solid #f1e0d0;padding:22px 24px;border-radius:12px;margin-bottom:22px;color:#8f683d}.report-verdict.eligible{background:#eff7f2;border-color:#d5e8db;color:#397359}.report-verdict strong{font-size:15px}.report-verdict p,.report-verdict li{font-size:12px;line-height:1.7}.report-verdict p{margin:6px 0 0}.report-verdict ul{padding-left:16px;margin-bottom:0}.report-card{background:#fff;border:1px solid #e7e8ee;border-radius:12px;margin-bottom:20px;overflow:hidden}.report-card>header{display:flex;justify-content:space-between;align-items:center;padding:20px 24px;border-bottom:1px solid #eeeef3}.report-card h3{font-size:14px;margin:0}.snapshot-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;padding:24px}.snapshot-grid span{display:block;color:#999ca8;font-size:11px;margin-bottom:9px}.snapshot-grid b{font-size:12px;font-weight:500;overflow-wrap:anywhere}.sample-heading{width:100%;display:flex;gap:18px;align-items:center;text-align:left;padding:20px 24px;border:0;background:white;cursor:pointer;color:#111849;font:inherit;border-bottom:1px solid #f0f0f5}.sample-heading strong{font-size:13px;margin-right:auto}.sample-index{color:#a1a5b1;font-size:11px;font-variant-numeric:tabular-nums}.sample-body{padding:10px 24px 25px;background:#fcfcfd}.sample-body h4{font-size:12px;font-weight:500;color:#8a90a0}.sample-body pre{min-height:80px;font-size:12px;background:white}.sample-measures{display:flex;gap:8px 14px;font-size:11px;flex-wrap:wrap}.sample-measures dt{color:#8f94a2}.sample-measures dd{margin:0 15px 0 0}.voice-matrix,.comparison-note{font-size:12px;padding:16px 24px;color:#7e8495;margin:0;background:#fafafd}.comparison-note{display:flex;justify-content:space-between;gap:10px}@media(max-width:1100px){.report-heading{align-items:flex-start;flex-direction:column}.snapshot-grid{grid-template-columns:1fr 1fr}}
</style>
